/* RETRO_LANGUAGE_ES */

#define ODIN_RENDERER_LABEL_ES "Renderizador (es necesario reiniciar)"
#define ODIN_RENDERER_INFO_0_ES "OpenGL o Vulkan. El valor automático elegirá el equivalente elegido en el controlador de vídeo de RetroArch (glcore o vulkan)."
#define OPTION_VAL_AUTO_ES "Automática"
#define OPTION_VAL_OPENGL_ES NULL
#define OPTION_VAL_VULKAN_ES NULL
#define ODIN_SCALE_LABEL_ES "Resolución interna"
#define ODIN_SCALE_INFO_0_ES "Los elementos 3D se renderizarán a una resolución superior que los 640 × 480 de la pantalla original de la placa, las capas en 2D se mantendrán tal cual."
#define OPTION_VAL_1_ES "× 1 (640 × 480)"
#define OPTION_VAL_2_ES "× 2 (1280 × 960)"
#define OPTION_VAL_3_ES "× 3 (1920 × 1440)"
#define OPTION_VAL_4_ES "× 4 (2560 × 1920)"
#define OPTION_VAL_5_ES "× 5 (3200 × 2400)"
#define OPTION_VAL_6_ES "× 6 (3840 × 2880)"
#define ODIN_UPSCALE_MODE_LABEL_ES "Interfaz en resoluciones elevadas"
#define ODIN_UPSCALE_MODE_INFO_0_ES "Establece la forma de dibujar las mallas fijas en pantallas (la interfaz, sus textos...) a resoluciones superiores a × 1: Acoplada para que sus esquinas respeten los píxeles de la placa (el valor predeterminado), Nativa para que se muestren sobre los píxeles que cubran, En bruto para que se muestren igual que el resto."
#define OPTION_VAL_SNAP_ES "Ajustar"
#define OPTION_VAL_NATIVE_ES "Nativa"
#define OPTION_VAL_RAW_ES "Datos en bruto"
#define ODIN_THREADED_LABEL_ES "Placa multihilo (es necesario reiniciar)"
#define ODIN_THREADED_INFO_0_ES "La placa ejecutará el siguiente fotograma en un hilo independiente mientras se está dibujando el fotograma anterior, tal y como hace la versión para escritorio de Odin: es más rápido en la mayoría de equipos y añade un fotograma de latencia. Desactiva esta opción para que se ejecute y renderice cada fotograma por turnos."
#define ODIN_RUMBLE_LABEL_ES "Vibración"
#define ODIN_RUMBLE_INFO_0_ES "Los mandos vibrarán de la misma forma que vibraría el mueble: las salidas de vibración, el dispositivo de vibración de la placa de sonido opcional (Star Wars Racer Arcade) y las sacudidas del volante (NASCAR Arcade), tal y como haría la versión de escritorio de Odin con un mando. Solo el motor grande no moverá el motor pequeño, para aquellos mandos en los que las sacudidas de un volante sean excesivas."
#define OPTION_VAL_LARGE_ES "Solo el motor grande"
#define ODIN_PHARRIER_SOUND_MODE_LABEL_ES "Modo de sonido"
#define ODIN_PHARRIER_SOUND_MODE_INFO_0_ES "Planet Harriers tiene una placa de sonido opcional: Principal para usar solo la placa principal; Ambas para mezclar las dos y ajustar el volumen de la opcional con su opción correspondiente; 4.0 es el ajuste cuadrafónico de la versión de escritorio: cuatro canales, la placa principal se reproduce por los dos frontales y la opcional por los traseros con el volumen ajustado con su opción correspondiente (RetroArch la convierte en estéreo, si RetroArch no tiene sonido multicanal, reproducirá ambas); Solo opcional para reproducir solo la placa opcional."
#define OPTION_VAL_MAIN_ES "Principal"
#define OPTION_VAL_MIX_ES "Ambos"
#define OPTION_VAL_QUAD_ES NULL
#define OPTION_VAL_OPTION_ES "Solo opcional"
#define ODIN_PHARRIER_OPTION_LEVEL_LABEL_ES "Volumen de placa opcional"
#define ODIN_PHARRIER_OPTION_LEVEL_INFO_0_ES "Ajusta el volumen de la placa de sonido opcional de Planet Harriers respecto a la placa principal si el modo de sonido está configurado como Ambas."
