#define ODIN_SWRACER_SOUND_MODE_INFO_0_ES "Star Wars Racer Arcade tiene una placa de sonido opcional: Principal para usar solo la placa principal; Ambas para mezclar las dos y ajustar el volumen de la opcional con su opción correspondiente; 4.0 es el ajuste cuadrafónico de la versión de escritorio: cuatro canales, la placa principal se reproduce por los dos frontales y la opcional por los traseros con el volumen ajustado con su opción correspondiente (RetroArch la convierte en estéreo, si RetroArch no tiene sonido multicanal, reproducirá ambas); Solo opcional para reproducir solo la placa opcional."
#define ODIN_SWRACER_OPTION_LEVEL_INFO_0_ES "Ajusta el volumen de la placa de sonido opcional de Star Wars Racer Arcade respecto a la placa principal si el modo de sonido está configurado como Ambas."
#define ODIN_SGNASCAR_SOUND_MODE_INFO_0_ES "NASCAR Arcade tiene una placa de sonido opcional: Principal para usar solo la placa principal; Ambas para mezclar las dos y ajustar el volumen de la opcional con su opción correspondiente; 4.0 es el ajuste cuadrafónico de la versión de escritorio: cuatro canales, la placa principal se reproduce por los dos frontales y la opcional por los traseros con el volumen ajustado con su opción correspondiente (RetroArch la convierte en estéreo, si RetroArch no tiene sonido multicanal, reproducirá ambas); Solo opcional para reproducir solo la placa opcional."
#define ODIN_SGNASCAR_OPTION_LEVEL_INFO_0_ES "Ajusta el volumen de la placa de sonido opcional de NASCAR Arcade respecto a la placa principal si el modo de sonido está configurado como Ambas o como 4.0: de -24 dB a 0 (sus motores suenan muy fuerte)."
