#define OPTION_VAL_SNAP_GA NULL
#define OPTION_VAL_NATIVE_GA "Dúchasach"
#define OPTION_VAL_RAW_GA "Amh"
#define ODIN_THREADED_LABEL_GA "Clár Snáithithe (Atosaigh)"
#define ODIN_THREADED_INFO_0_GA "Ritheann an bord an chéad fhráma eile ar shnáithe dá chuid féin fad is atá an fráma roimhe sin á tharraingt, díreach mar a dhéanann Odin ar an deasc: bíonn sé níos tapúla ar fhormhór na meaisíní, ach bíonn moill bhreise aon fhráma amháin i gceist. As: déantar gach fráma a rith agus a tharraingt ceann i ndiaidh a chéile."
#define ODIN_RUMBLE_LABEL_GA "Tormán"
#define ODIN_RUMBLE_INFO_0_GA "Croitheann na rialtóirí díreach mar a chroitheann an comh-aireachta féin: trína thorann, trí ghléas creathadh a bhíonn á thiomáint ag an gclár fuaime roghnach (i gcás *Star Wars Racer Arcade*), agus trí chreathadh an rotha stiúrtha (i gcás *NASCAR Arcade*) — díreach mar a chroitheann an t-aonad deisce Odin rialtóir cluiche. Fágann an socrú \"Mótar Mór Amháin\" (Large Motor Only) an mótar beag gan gluaiseacht; úsáidtear é seo i gcásanna ina mbeadh creathadh an rotha stiúrtha ró-láidir don rialtóir."
#define OPTION_VAL_LARGE_GA "Mótar Mór Amháin"
#define ODIN_PHARRIER_SOUND_MODE_LABEL_GA "Mód Fuaime"
#define ODIN_PHARRIER_SOUND_MODE_INFO_0_GA "Tá bord fuaime roghnach ag Planet Harriers: Main, an príomhbhord amháin; Both, an dá cheann measctha, leis an gceann roghnach ag leibhéal an bhoird roghnaigh; 4.0, ar nós an chórais 'Quad' ar ríomhaire deisce: ceithre chainéal, an príomhbhord sna callairí tosaigh, agus an bord roghnach sna callairí cúil ag leibhéal an bhoird roghnaigh (déanann RetroArch iad a chomhcheangal le haghaidh steirió; má bhíonn RetroArch in úsáid nach dtacaíonn le fuaim ilchainéil, roghnófar an socrú 'Both'); Optional Only, an bord roghnach amháin."
