#define ODIN_SWRACER_SOUND_MODE_INFO_0_GA "Tá bord fuaime roghnach ag *Star Wars Racer Arcade*: 'Main' (an príomhbhord amháin); 'Both' (an dá cheann measctha le chéile, leis an mbord roghnach ag leibhéal an bhoird roghnaigh); '4.0' (cosúil le cumraíocht 'Quad' ar ríomhaire deisce: ceithre chainéal, leis an bpríomhbhord sna callairí tosaigh agus an bord roghnach sna callairí cúil ag leibhéal an bhoird roghnaigh — déanann RetroArch iad a chomhcheangal le haghaidh steirió; má bhíonn RetroArch in úsáid nach dtacaíonn le fuaim ilchainéil, roghnófar 'Both'); agus 'Optional Only' (an bord roghnach amháin)."
#define ODIN_SWRACER_OPTION_LEVEL_INFO_0_GA "An bord fuaime roghnach de Star Wars Racer Arcade i gcomparáid leis an bpríomhbhord, agus 'Sound Mode' socraithe ar 'Both'."
#define ODIN_SGNASCAR_SOUND_MODE_INFO_0_GA "Tá bord fuaime roghnach ag NASCAR Arcade: *Main* (an príomhbhord amháin); *Both* (an dá cheann measctha le chéile, leis an mbord roghnach ag leibhéal an bhoird roghnaigh); *4.0* (cosúil le córas ceithre chainéal an deisce: an príomhbhord sna callairí tosaigh, agus an bord roghnach sna callairí cúil ag leibhéal an bhoird roghnaigh — déanann RetroArch iad a chomhcheangal i mód steirió; má bhíonn RetroArch in úsáid nach dtacaíonn le fuaim ilchainéil, roghnófar *Both*); agus *Optional Only* (an bord roghnach amháin)."
#define ODIN_SGNASCAR_OPTION_LEVEL_INFO_0_GA "An bord fuaime roghnach de NASCAR Arcade i gcomparáid leis an bpríomhbhord, agus 'Sound Mode' socraithe ar 'Both' nó '4.0': -24 dB go 0 dB (tá a innill glórach)."
