#define ODIN_ATVTRACK_SOUND_MODE_INFO_0_GA "Tá *woofer* ag an ATV Track, a fhaigheann comhartha ón dara péire cainéal ar an gclár: *Main* – na callairí amháin; *Both* – minicíochtaí ísle an *woofer* measctha isteach ag leibhéal socraithe (*Woofer Level*), de réir mar a sheinntear an t-ábhar ar an deasc; *4.0* – ceithre chainéal, leis na callairí chun tosaigh agus cainéal an *woofer* ar chúl (déanann RetroArch iad a chomhcheangal i bhformáid steirió; má bhíonn RetroArch in úsáid gan tacaíocht fuaime ilchainéil, roghnófar an socrú *Both*); *Woofer Only* – an *woofer* amháin: na minicíochtaí ísle ón gcainéal sin atá faoi bhun an phointe scoite (*Woofer Cutoff*)."
#define OPTION_VAL_OPTION_ODIN_ATVTRACK_SOUND_MODE_GA "Woofer Amháin"
#define ODIN_ATVTRACK_OPTION_LEVEL_LABEL_GA "Leibhéal an Woofer"
#define ODIN_ATVTRACK_OPTION_LEVEL_INFO_0_GA "An woofer ar an ATV Track i gcomparáid leis na callairí, le mód fuaime socraithe ar 'An Dá Cheann', '4.0' nó 'Woofer Amháin'."
#define ODIN_ATVTRACK_WOOFER_CUTOFF_LABEL_GA "Minicíocht Ghearrtha an Woofer"
#define ODIN_ATVTRACK_WOOFER_CUTOFF_INFO_0_GA "Seinntear minicíochtaí ísle chainéal an woofer nuair a roghnaítear an Mód Fuaime 'Both' (An Dá Cheann) nó 'Woofer Only' (Woofer Amháin): faoi bhun líon áirithe Hz, nó an raon ar fad (Múchta)."
#define OPTION_VAL_80_GA NULL
#define OPTION_VAL_120_GA NULL
