#define OPTION_VAL_200_GA NULL
#define ODIN_GFOOTBAL_SOUND_MODE_INFO_0_GA "Tá *woofer* ag Gaelco Football, a fhaigheann comhartha ón dara péire cainéal ar an gclár: *Main* (na callairí amháin); *Both* (na minicíochtaí ísle ón *woofer* measctha isteach ag leibhéal ar leith, agus an cluiche á imirt ar an deasc); *4.0* (ceithre chainéal: na callairí chun tosaigh agus cainéal an *woofer* ar chúl — déanann RetroArch iad a chomhcheangal le haghaidh steiréó; má bhíonn RetroArch in úsáid nach dtacaíonn le fuaim ilchainéil, roghnófar *Both*); agus *Woofer Only* (an *woofer* amháin: na minicíochtaí ísle óna chainéal féin, faoi bhun phointe scoite an *woofer*)."
#define ODIN_GFOOTBAL_OPTION_LEVEL_INFO_0_GA "An dordchainteoir de chuid Gaelco Football i gcomhar leis na cainteoirí, agus an Mód Fuaime socraithe ar 'An Dá Cheann', '4.0' nó 'Dordchainteoir Amháin'."
#define ODIN_SMASHDRV_SOUND_MODE_INFO_0_GA "Tá cainteoir cantaire ag Smashing Drive, a bheathaítear ag an dara péire cainéal ar an mbord: Main, na cainteoirí leo féin; An dá cheann, measctar ísealfhuaimeanna an cainteoir ag Leibhéal an Chainteoir, agus an deasc á sheinm; 4.0, ceithre chainéal, na cainteoirí chun tosaigh agus cainéal an cainteoir cantaire sa chúl (fillteann RetroArch iad le haghaidh steiréó; faigheann RetroArch gan fhuaim ilchainéil an dá cheann); Woofer Only, an cainteoir cantaire leis féin: ísealfhuaimeanna a chainéil faoi bhun Gearradh an Chainteoir."
#define ODIN_SMASHDRV_OPTION_LEVEL_INFO_0_GA "An woofer de chuid Smashing Drive i gcoinne na gcainteoirí, agus an Mód Fuaime socraithe ar 'Both', '4.0' nó 'Woofer Only'."
#define ODIN_SMASHDRV_START_VOLUME_LABEL_GA "Toirt Tosaigh"
#define ODIN_SMASHDRV_START_VOLUME_INFO_0_GA "Socraítear an leibhéal fuaime do 'Smashing Drive' gach uair a chuirtear an gléas ar siúl, ar an gcaoi chéanna a dhéanfadh oibreoir leis na cnaipí VOLUME - agus VOLUME + (ní choinníonn an bord aon socruithe dá chuid féin ar dtús)."
#define ODIN_ANISOTROPY_LABEL_GA "Scagadh Ainiseatrópach"
