/* RETRO_LANGUAGE_VN */

#define ODIN_RENDERER_LABEL_VN "Bộ kết xuất (Khởi động lại)"
#define ODIN_RENDERER_INFO_0_VN "OpenGL hoặc Vulkan. Tự động sẽ chọn trình điều khiển video mà RetroArch đang sử dụng (glcore hoặc vulkan)."
#define OPTION_VAL_AUTO_VN "Tự động"
#define OPTION_VAL_OPENGL_VN NULL
#define OPTION_VAL_VULKAN_VN NULL
#define ODIN_SCALE_LABEL_VN "Độ phân giải nội bộ"
#define ODIN_SCALE_INFO_0_VN "Hình ảnh 3D được kết xuất với độ phân giải cao gấp bấy nhiêu lần so với màn hình 640x480 của máy chơi game; các lớp hình ảnh 2D vẫn giữ nguyên."
#define OPTION_VAL_1_VN NULL
#define OPTION_VAL_2_VN NULL
#define OPTION_VAL_3_VN NULL
#define OPTION_VAL_4_VN NULL
#define OPTION_VAL_5_VN NULL
#define OPTION_VAL_6_VN NULL
#define ODIN_UPSCALE_MODE_LABEL_VN "Giao diện trò chơi ở độ phân giải cao hơn"
#define ODIN_UPSCALE_MODE_INFO_0_VN "Cách các lớp hình ảnh phẳng trên màn hình (giao diện trò chơi, chữ hiển thị) được kết xuất ở mức trên 1x: Căn khớp, các góc của chúng khớp với điểm ảnh trên màn hình máy chơi game (mặc định); Nguyên bản, hiển thị chồng lên các điểm ảnh mà chúng bao phủ; Thô, có độ chi tiết cao như các thành phần còn lại."
#define OPTION_VAL_SNAP_VN "Căn khớp"
#define OPTION_VAL_NATIVE_VN "Nguyên bản"
#define OPTION_VAL_RAW_VN "Nguyên bản - Raw"
#define ODIN_THREADED_LABEL_VN "Chạy máy chơi game bằng luồng riêng (Khởi động lại)"
#define ODIN_THREADED_INFO_0_VN "Máy chơi game xử lý khung hình tiếp theo trên một luồng riêng trong khi khung hình trước đó đang được kết xuất, giống như bản Odin dành cho máy tính: nhanh hơn trên hầu hết thiết bị, nhưng tăng thêm độ trễ một khung hình. Tắt: từng khung hình được xử lý và kết xuất lần lượt."
#define ODIN_RUMBLE_LABEL_VN "Rung"
#define ODIN_RUMBLE_INFO_0_VN "Tay cầm rung theo phản hồi rung của tủ máy: các đầu ra rung của máy, thiết bị rung do bảng âm thanh tùy chọn điều khiển (Star Wars Racer Arcade) và lực giật của vô lăng (NASCAR Arcade), tương tự như cách bản Odin dành cho máy tính làm tay cầm chơi game rung. Chỉ mô-tơ lớn giữ cho mô-tơ nhỏ không rung, dành cho loại tay cầm mà lực giật của vô lăng quá mạnh."
#define OPTION_VAL_LARGE_VN "Chỉ mô-tơ lớn"
#define ODIN_PHARRIER_SOUND_MODE_LABEL_VN "Chế độ âm thanh"
#define ODIN_PHARRIER_SOUND_MODE_INFO_0_VN "Planet Harriers có bảng âm thanh tùy chọn: Chỉ bảng chính, chỉ sử dụng bảng chính; Cả hai, trộn âm thanh từ hai bảng, bảng tùy chọn được đặt ở mức âm lượng của bảng tùy chọn; 4.0, giống chế độ bốn kênh của bản Odin dành cho máy tính: bảng chính phát qua loa trước, bảng tùy chọn phát qua loa sau ở mức âm lượng của bảng tùy chọn (RetroArch sẽ gộp các kênh thành âm thanh nổi; phiên bản RetroArch không hỗ trợ âm thanh đa kênh sẽ sử dụng chế độ Cả hai); Chỉ bảng tùy chọn, chỉ sử dụng bảng âm thanh tùy chọn."
#define OPTION_VAL_MAIN_VN "Mục chính"
#define OPTION_VAL_MIX_VN "Cả hai"
