#define ODIN_SWRACER_SOUND_MODE_INFO_0_VN "Star Wars Racer Arcade có bo mạch âm thanh tùy chọn: Chính, chỉ sử dụng bo mạch chính; Cả hai, trộn âm thanh từ hai bo mạch, âm lượng của bo mạch tùy chọn được điều chỉnh bằng Mức âm lượng bo mạch tùy chọn; 4.0, tương tự chế độ âm thanh vòm bốn kênh trên máy tính: bốn kênh, bo mạch chính phát qua loa trước, bo mạch tùy chọn phát qua loa sau với âm lượng được điều chỉnh bằng Mức âm lượng bo mạch tùy chọn (RetroArch sẽ trộn các kênh này thành âm thanh nổi; phiên bản RetroArch không hỗ trợ âm thanh đa kênh sẽ sử dụng chế độ Cả hai); Chỉ bo mạch tùy chọn, chỉ sử dụng bo mạch tùy chọn."
#define ODIN_SWRACER_OPTION_LEVEL_INFO_0_VN "So sánh bo mạch âm thanh tùy chọn của Star Wars Racer Arcade với bo mạch chính, khi Chế độ âm thanh được đặt thành Cả hai."
#define ODIN_SGNASCAR_SOUND_MODE_INFO_0_VN "NASCAR Arcade có bo mạch âm thanh tùy chọn: Chính, chỉ sử dụng bo mạch chính; Cả hai, trộn âm thanh từ hai bo mạch, âm lượng của bo mạch tùy chọn được điều chỉnh bằng Mức âm lượng bo mạch tùy chọn; 4.0, tương tự chế độ âm thanh vòm bốn kênh trên máy tính: bốn kênh, bo mạch chính phát qua loa trước, bo mạch tùy chọn phát qua loa sau với âm lượng được điều chỉnh bằng Mức âm lượng bo mạch tùy chọn (RetroArch sẽ trộn các kênh này thành âm thanh nổi; phiên bản RetroArch không hỗ trợ âm thanh đa kênh sẽ sử dụng chế độ Cả hai); Chỉ bo mạch tùy chọn, chỉ sử dụng bo mạch tùy chọn."
#define ODIN_SGNASCAR_OPTION_LEVEL_INFO_0_VN "Điều chỉnh âm lượng bo mạch âm thanh tùy chọn của NASCAR Arcade so với bo mạch chính, khi Chế độ âm thanh được đặt thành Cả hai hoặc 4.0: từ -24 dB đến 0 dB (tiếng động cơ trong trò chơi rất lớn)."
