#define ODIN_ATVTRACK_SOUND_MODE_INFO_0_VN "ATV Track có loa siêu trầm, được cấp tín hiệu từ cặp kênh thứ hai của bo mạch: Chính, chỉ phát âm thanh qua các loa; Cả hai, trộn âm trầm của loa siêu trầm vào tín hiệu âm thanh theo mức Âm lượng loa siêu trầm, giống như cách máy tính để bàn phát âm thanh; 4.0, sử dụng bốn kênh, các loa ở phía trước và kênh loa siêu trầm ở phía sau (RetroArch sẽ gộp các kênh này thành âm thanh nổi; nếu RetroArch không hỗ trợ âm thanh đa kênh thì sẽ sử dụng chế độ Cả hai); Chỉ loa siêu trầm, chỉ phát âm thanh qua loa siêu trầm: phần âm trầm của kênh này nằm dưới Tần số cắt loa siêu trầm."
#define OPTION_VAL_OPTION_ODIN_ATVTRACK_SOUND_MODE_VN "Chỉ loa siêu trầm"
