#define ODIN_ATVTRACK_OPTION_LEVEL_INFO_0_VN "Âm lượng của loa siêu trầm ATV Track so với các loa thông thường, khi Chế độ âm thanh được đặt thành Cả hai, 4.0 hoặc Chỉ loa siêu trầm."
#define ODIN_ATVTRACK_WOOFER_CUTOFF_LABEL_VN "Tần số cắt loa siêu trầm"
#define ODIN_ATVTRACK_WOOFER_CUTOFF_INFO_0_VN "Phần âm trầm của kênh loa siêu trầm được phát khi Chế độ âm thanh được đặt thành Cả hai và Chỉ loa siêu trầm: các tần số thấp hơn mức Hz được chỉ định sẽ được phát, hoặc phát toàn bộ dải tần (Tắt)."
